package pe.edu.upeu.bomerp.administracion.web;
import pe.edu.upeu.bomerp.administracion.model.*;import pe.edu.upeu.bomerp.administracion.repository.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.access.prepost.PreAuthorize;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import java.util.*;
@RestController @RequestMapping("/api/gestion/almacenes") @RequiredArgsConstructor @Transactional public class AlmacenCrud {
 private final AlmacenRepository repo;private final SucursalRepository sucursalRepo;
 @GetMapping public List<Almacen> listar(){return repo.findAll();}
 @GetMapping("/{id}") public Almacen obtener(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Registro no encontrado"));}
 @PostMapping @PreAuthorize("hasRole('ADMIN')") public Almacen crear(@Valid @RequestBody Almacen r){var e=new Almacen();e.setNombre(r.getNombre());e.setTipo(r.getTipo());if(r.getSucursal()==null||r.getSucursal().getId()==null)throw new IllegalArgumentException("Selecciona Sucursal");e.setSucursal(sucursalRepo.findById(r.getSucursal().getId()).filter(x->x.isActivo()).orElseThrow(()->new IllegalArgumentException("Sucursal no existe o está inactivo")));return repo.save(e);}
 @PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public Almacen actualizar(@PathVariable Long id,@Valid @RequestBody Almacen r){var e=obtener(id);e.setNombre(r.getNombre());e.setTipo(r.getTipo());if(r.getSucursal()==null||r.getSucursal().getId()==null)throw new IllegalArgumentException("Selecciona Sucursal");e.setSucursal(sucursalRepo.findById(r.getSucursal().getId()).filter(x->x.isActivo()).orElseThrow(()->new IllegalArgumentException("Sucursal no existe o está inactivo")));return repo.save(e);}
 @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public void eliminar(@PathVariable Long id){repo.delete(obtener(id));repo.flush();}
}